def test_reference_payload_requires_resolution_and_digest(sample):
    """dataref 不能仅凭 URI 被信任，JSON 摘要与具体 payload schema 都必须核对。"""
    body = sample.intent.data
    uri = "urn:april:payload:synthetic"
    def as_reference(intent):
        """使用与 inline 同一份规范化 metadata JSON。"""
        intent.update(data=None, dataref=uri, datadigest="sha256:" + canonical_sha256(body))
    submission = with_intent(sample, as_reference)
    assert prepare(sample, submission, referenced_data={uri: body}).verified_roots == sample.roots
    with pytest.raises(ValueError):
        prepare(sample, submission)
    with pytest.raises(ValueError):
        prepare(sample, submission, referenced_data={uri: body | {"job_id": "different"}})


