def test_violation_ignores_ordinary_outputs_but_keeps_control_only_epochs(sample):
    """V9 不因非法普通事件变成外层拒绝，未执行输出不充当已验证来源。"""
    request = sample.request.model_dump()
    page = sample.request.bundle.page_result.page.model_copy(deep=True)
    page.continuations.append(Continuation(checkpoint=page.checkpoint_after))
    page.tombstones.append(tombstone("doc-hash"))
    classified = classify_collection_page(sample.request.bundle.page_result.reference, page, sample.decision_context, sample.task.context, authorized_sources=frozenset({sample.task.source_id}), policy=sample.parts.policy, expected_lock=sample.configuration.decision_policy)
    result = classified.page_result.model_copy(update={"reference": page_result_reference(sample.task.task_id, 1, classified.page_result)})
    request["bundle"]["page_result"] = result.model_dump()
    # 故意放不可执行的普通内容，合法控制仍走独立通道；原包全部字段仍被摘要覆盖。
    request["bundle"]["outbound_events"][0]["payload"] = {"not_an_event": "ignored"}
    material = prepare(sample, SubmissionRequest(**request))
    assert material.verified_roots.objects == []
    assert [epoch.target.object_id for epoch in material.pre_control_epochs] == ["doc-hash"]
    assert material.control_report.checks[0].decision == "accepted"
    assert result.violation_codes == ["V9"]


